422	fn rand_u32() -> u32 {
423	    static mut SEED: u32 = 123456789;
424	    unsafe {
425	        SEED ^= SEED << 13;
426	        SEED ^= SEED >> 17;
427	        SEED ^= SEED << 5;
428	        SEED
