 72	/// Register a custom solver. If the id already exists, it is replaced.
 73	pub fn register_solver(solver: Arc<dyn VRPSolver>) {
 74	    let id = solver.id().to_string();
 75	    let mut reg = registry().write().unwrap();
 76	    let had = reg.solvers.contains_key(&id);
 77	    reg.solvers.insert(id.clone(), solver);
 78	    if !had && !reg.builtin_ids.contains(&id) {
 79	        reg.dynamic_order.push(id);
 80	    }
 81	}
 82	
 83	/// Unregister a solver by id. Built-in solver ids are ignored.
 84	/// Returns true if a dynamic solver was removed.
 85	pub fn unregister_solver(id: &str) -> bool {
 86	    let mut reg = registry().write().unwrap();
 87	    if reg.builtin_ids.contains(&id.to_string()) {
 88	        return false;
 89	    }
 90	    let removed = reg.solvers.remove(id).is_some();
 91	    if removed {
 92	        reg.dynamic_order.retain(|x| x != id);
 93	    }
 94	    removed
 95	}
