 4	use super::super::types::*;
 5	use super::super::utils::{matrix_get_dist, matrix_get_time};
 6	
 7	fn solve(matrix: &DistMatrix, locations: &[VRPSolverStop], num_vehicles: usize) -> SolveResult {
 8	    let n = matrix.len();
 9	    if n <= 1 {
10	        return SolveResult {
11	            routes: vec![vec![0]],
12	            total_distance: 0.0,
13	            total_time: 0.0,
14	        };
15	    }
16	
17	    let route_indices = crate::core::vrp::utils::build_sweep_routes(matrix, locations, num_vehicles);
18	
19	    let mut total_distance = 0.0;
20	    let mut total_time = 0.0;
21	    for r in &route_indices {
22	        for k in 0..r.len() - 1 {
23	            total_distance += matrix_get_dist(matrix, r[k], r[k + 1]);
24	            total_time += matrix_get_time(matrix, r[k], r[k + 1]);
25	        }
26	    }
27	
28	    SolveResult {
29	        routes: route_indices,
30	        total_distance,
31	        total_time,
32	    }
33	}
