import json
from collections import Counter, defaultdict

def load(path):
    entries = []
    with open(path) as f:
        for line in f:
            if line.strip():
                entries.append(json.loads(line))
    return entries

entries = load('data/training_data.jsonl')

# For each solver, count instances where it's within X% of best
for threshold in [0.02, 0.05, 0.10, 0.20]:
    print(f'\nThreshold: within {threshold*100:.0f}% of best')
    counts = Counter()
    for e in entries:
