 44	}
 45	
 46	impl SolverRegistryInner {
 47	    fn new() -> Self {
 48	        let mut builtins: Vec<Arc<dyn VRPSolver>> = vec![
 49	            Arc::new(ClarkeWrightSolver),
 50	            Arc::new(SweepSolver),
 51	            Arc::new(OrOptSolver),
 52	            Arc::new(TwoOptSolver),
